    S(962, 'ローマでの戴冠', 'ローマ', 12.45, 41.90, 0.6, ['otto-1'], ['hre', 'papal', 'byzantine'],
      '教皇ヨハネス12世に助けを求められたオットーはイタリアに入り、962年、ローマのサン=ピエトロ大聖堂で皇帝の冠を受けた。これが神聖ローマ帝国の始まりとされる。オットーは教皇選びにも口を出し、皇帝と教皇の関係はのちの対立の種となった。',
      '962年2月2日、ローマのサン=ピエトロ大聖堂。教皇ヨハネス12世は、オットーに皇帝の冠をさずけました。カール大帝の戴冠から、160年あまり。のちに神聖ローマ帝国とよばれる国の始まりです。ところが、教皇はまもなくオットーにそむきます。オットーは教皇を退け、新しい教皇を立てました。皇帝が教皇を選ぶ。このやり方は、のちの叙任権闘争という大きな争いの種になります。',
      { marks: [{ name: 'サン=ピエトロ大聖堂', lon: 12.4534, lat: 41.9022 }],
        routes: [{ name: 'ローマへの道', color: '#7a1f1f', pts: [[9.16, 45.19], [10.3, 44.8], [11.34, 44.49], [11.25, 43.77], [12.0, 42.4], [12.45, 41.9]] }] }),
    S(968, '帝国教会政策と東への布教', 'マクデブルク', 11.63, 52.13, 6, ['otto-1'], ['hre', 'poland'],
      'オットーは、跡つぎをめぐって争う諸侯をおさえるため、結婚しない司教や修道院長に土地と役職を与えて味方とした（帝国教会政策）。968年、愛した町マクデブルクに大司教座を置き、エルベ川の東のスラヴ人への布教の拠点とした。',
      '公たちは、自分の領地を子に継がせ、王にさからうことがあります。そこでオットーは、教会の司教や修道院長に、土地や役所の仕事を与えました。司教は結婚しないので、領地を自分の子に継がせることができません。王が次の司教を選べば、ずっと味方でいてくれるのです。これを帝国教会政策といいます。968年、オットーは愛した町マクデブルクに大司教を置き、エルベ川の東に住むスラヴ人へキリスト教を広げる拠点にしました。',
      { lines: [{ name: 'エルベ川', pts: [[11.7, 51.9], [11.63, 52.13], [11.8, 52.5], [12.0, 52.9], [11.0, 53.4]] }],
        marks: [{ name: 'ポーランド（966年にキリスト教を受け入れる）', lon: 17.0, lat: 52.4 }] }),
    S(973, 'マクデブルクに眠る', 'マクデブルク', 11.63, 52.13, 1, ['otto-1'], ['hre'],
      'オットーは息子オットー2世にビザンツ帝国の皇女テオファヌをむかえ、東の帝国とも和解した。973年、父が亡くなったのと同じメムレーベンで死去し、マクデブルク大聖堂に葬られた。のちにオットー大帝とよばれる。',
      '晩年のオットーは、東のビザンツ帝国とも話しあい、息子オットー2世の妻として、ビザンツの皇女テオファヌをむかえました。東と西の皇帝が手を結んだのです。973年5月、オットーは、父が亡くなったのと同じ町メムレーベンで、ミサのあとにたおれ、亡くなりました。60歳でした。遺体はマクデブルクの大聖堂に、最初の妻のとなりに葬られています。彼はのちに、オットー大帝とよばれました。',
      { marks: [{ name: 'マクデブルク大聖堂', lon: 11.634, lat: 52.124 }, { name: 'メムレーベン（死去の地）', lon: 11.5, lat: 51.27 }] })
